  button(importBtn,"IMPORT WAV",panel2);button(saveBtn,"SAVE",panel2);button(openBtn,"OPEN",panel2);text(d,win,gc,25,192,"BROWSER",muted);text(d,win,gc,25,218,"Native Drums",txt);for(int i=0;i<static_cast<int>(nativeDrumChoices().size());++i){auto r=nativeDrumRect(i);fill(d,win,gc,r,i==selectedLane?panel2:rgb(d,31,33,38));text(d,win,gc,r.x+8,r.y+16,nativeDrumChoices()[static_cast<std::size_t>(i)].first,txt);}text(d,win,gc,25,590,"Chop keys",muted);text(d,win,gc,25,615,"1 2 3 4",txt);text(d,win,gc,25,637,"Q W E R",txt);text(d,win,gc,25,659,"A S D F",txt);text(d,win,gc,25,681,"Z X C V",txt);text(d,win,gc,25,730,"Space  Play/Pause",muted);text(d,win,gc,25,750,"Ctrl+S Save",muted);text(d,win,gc,25,770,"Ctrl+Z Undo",muted);
