  if(auto*c=clip()){auto r=clipRect();fill(d,win,gc,r,purple);auto*s=activeAudioSample();text(d,win,gc,r.x+8,r.y+17,s?s->name:"Audio",txt);if(!waveform.empty()){int mid=r.y+r.h/2;std::size_t count=std::min<std::size_t>(waveform.size(),static_cast<std::size_t>(std::max(1,r.w-10)));for(std::size_t i=0;i<count;++i){auto idx=i*waveform.size()/count;int x=r.x+5+static_cast<int>(i);line(d,win,gc,x,mid-static_cast<int>(waveform[idx].second*(r.h/2-19)),x,mid-static_cast<int>(waveform[idx].first*(r.h/2-19)),txt);}if(s&&s->audio&&s->audio->frames()>0)for(auto const&sl:s->slices){int sx=r.x+static_cast<int>((static_cast<double>(sl.startFrame)/s->audio->frames())*r.w);line(d,win,gc,sx,r.y,sx,r.y+r.h,orange);}}(void)c;}else text(d,win,gc,browserW+44,audioTrackY+55,"Import WAV -> Analyze -> Chop -> play pads",muted);
