  fill(d,win,gc,{browserW+18,editorY-8,600,205},panel);text(d,win,gc,browserW+34,editorY+18,"STEP / HUMAN FEEL",muted);if(auto*p=pattern();p&&selectedLane<static_cast<int>(p->lanes.size())&&selectedStep<static_cast<int>(p->lanes[static_cast<std::size_t>(selectedLane)].steps.size())){auto&lane=p->lanes[static_cast<std::size_t>(selectedLane)];auto&st=lane.steps[static_cast<std::size_t>(selectedStep)];text(d,win,gc,250,660,"Step "+std::to_string(selectedStep+1)+"  "+lane.name,txt);button(velMinus,"-",panel2);button(velPlus,"+",panel2);text(d,win,gc,405,695,"Velocity "+std::to_string(static_cast<int>(st.velocity*100))+"%",txt);button(probMinus,"-",panel2);button(probPlus,"+",panel2);text(d,win,gc,570,695,"Prob "+std::to_string(static_cast<int>(st.probability*100))+"%",txt);button(microMinus,"-",panel2);button(microPlus,"+",panel2);text(d,win,gc,748,695,"Micro "+std::to_string(st.microTicks),txt);button(laneVolMinus,"-",panel2);button(laneVolPlus,"+",panel2);text(d,win,gc,405,735,"Lane vol "+std::to_string(static_cast<int>(lane.volume*100))+"%",txt);button(lanePanMinus,"-",panel2);button(lanePanPlus,"+",panel2);text(d,win,gc,570,735,"Pan "+oneDecimal(lane.pan),txt);}
